// The one month deadline in Art. 12 (3) GDPR is a calendar month, not 30 days.
// That is why setMonth is used: 31 January plus one month is 28 or 29 February,
// not 2 March. Counting 30 days is wrong in four months of the year.
function plusOneMonth(d) {
  const target = new Date(d.getTime());
  const day = target.getDate();
  target.setMonth(target.getMonth() + 1);
  if (target.getDate() < day) target.setDate(0); // pull an overflow back to the end of the month
  return target;
}
const iso = (d) => d.toISOString().slice(0, 10);

const out = [];
for (const entry of $input.all()) {
  const f = entry.json || {};
  const rawReceived = String(f['Date the request was received'] || '').trim();
  const received = rawReceived ? new Date(rawReceived) : new Date();
  const valid = !isNaN(received.getTime());
  const start = valid ? received : new Date();

  const deadline = plusOneMonth(start);
  const reminder = new Date(start.getTime() + 20 * 24 * 60 * 60 * 1000);
  const extension = plusOneMonth(plusOneMonth(deadline));

  const notes = [];
  if (!valid) notes.push('Date received could not be parsed - today was used instead, please check');
  if (valid && start.getTime() > Date.now() + 86400000) notes.push('Date received lies in the future - check for a typo');
  // A request logged late is the most common reason for a missed deadline.
  const daysOpen = Math.floor((Date.now() - start.getTime()) / 86400000);
  if (daysOpen > 20) notes.push('The request came in ' + daysOpen + ' days ago - the deadline is close, handle it now');
  if (String(f['Known relationship'] || '').startsWith('No')) notes.push('No known relationship - a negative answer is an answer too and bound to the same deadline');
  if (String(f['Copy of the data requested (Art. 15 (3))?'] || '') === 'Not clear') notes.push('Unclear whether a copy under Art. 15 (3) is requested - ask the requester');

  const serial = String(Date.now()).slice(-6);
  out.push({
    json: {
      case_id: 'DSR-' + start.getFullYear() + '-' + serial,
      received_date: iso(start),
      deadline_date: iso(deadline),
      reminder_date: iso(reminder),
      extension_possible_until: iso(extension),
      name: String(f['Name of the data subject'] || '').trim(),
      email: String(f['Email of the data subject'] || '').trim(),
      postal_address: String(f['Postal address'] || '').trim(),
      channel: String(f['Channel the request arrived through'] || ''),
      scope: String(f['Scope of the request'] || '').trim(),
      copy_requested: String(f['Copy of the data requested (Art. 15 (3))?'] || ''),
      relationship: String(f['Known relationship'] || ''),
      status: 'Received - identity check pending',
      identity_verified: 'no',
      notes: notes.join(' | ')
    }
  });
}
return out;

