// Art. 15 (1) GDPR lists eight mandatory items. An answer that only contains
// the data itself is incomplete, so this node builds a skeleton along (a) to
// (h) that the responsible person fills in or confirms. The list of systems is
// the real crux: forgotten sources are the most common reason for an
// incomplete answer.
const dsrCase = $('Calculate the deadlines').item.json;
const reply = $input.first().json || {};

// Adjust this list to your own system landscape.
const SOURCES = ['CRM', 'ERP / inventory management', 'Newsletter tool', 'Ticket system / support', 'Accounting', 'Applicant tracking', 'Phone system / call notes', 'Backups'];

const hits = Array.isArray(reply.hits) ? reply.hits : (Array.isArray(reply.results) ? reply.results : []);
const queried = hits.map(h => String(h.source || h.system || '')).filter(Boolean);
const openSources = SOURCES.filter(s => !queried.some(q => q.toLowerCase().includes(s.toLowerCase().split(' ')[0])));
const apiReachable = hits.length > 0 || Array.isArray(reply.hits);

const l = [];
l.push('# Draft answer under Art. 15 GDPR - ' + dsrCase.case_id);
l.push('');
l.push('Requester: ' + dsrCase.name + ' (' + dsrCase.email + ')');
l.push('Received: ' + dsrCase.received_date + ' | Deadline: ' + dsrCase.deadline_date);
l.push('Identity: confirmed by the responsible person on ' + new Date().toISOString().slice(0, 10));
l.push('');
l.push('## Mandatory items under Art. 15 (1)');
l.push('a) Purposes of the processing: [fill in]');
l.push('b) Categories of personal data concerned: [fill in]');
l.push('c) Recipients or categories of recipients, including third countries: [fill in]');
l.push('d) Envisaged storage period or the criteria used to determine it: [fill in]');
l.push('e) Note on rectification, erasure, restriction and objection: insert standard text');
l.push('f) Note on the right to lodge a complaint with a supervisory authority: insert standard text');
l.push('g) Source of the data where it was not collected from the person: [fill in]');
l.push('h) Automated decision making including profiling: [fill in, or deny explicitly]');
l.push('');
l.push('## Research result per data source');
if (hits.length === 0) {
  l.push('- No machine readable results. Query every source manually and document it here.');
} else {
  for (const h of hits) {
    l.push('- ' + (h.source || h.system || 'unnamed source') + ': ' + (h.count ?? h.records ?? 'unknown') + ' records' + (h.note ? ' (' + h.note + ')' : ''));
  }
}
l.push('');
l.push('## Sources still to be checked manually');
if (openSources.length === 0) l.push('- none');
for (const s of openSources) l.push('- ' + s + ' [enter the result, document a nil return as well]');
l.push('');
l.push('## Check before sending');
l.push('- Rights and freedoms of others (Art. 15 (4)): redact or remove third party data');
l.push('- Check national restrictions on the right of access');
l.push('- Copy under Art. 15 (3) requested: ' + dsrCase.copy_requested);
l.push('- Secure delivery: encrypted or registered post, not plain email');
l.push('- On refusal or partial answer: give reasons and point to the right to complain');

const warnings = [];
if (!apiReachable) warnings.push('Data source API not reachable or not configured - do the research fully manually');
if (openSources.length > 0) warnings.push(openSources.length + ' source(s) without a machine readable result');

return [{
  json: {
    ...dsrCase,
    identity_verified: 'yes',
    status: 'Draft created - review and delivery pending',
    open_sources: openSources.join(', '),
    warnings: warnings.join(' | '),
    draft: l.join('\n')
  }
}];

